<div class="auth-shell"><div class="auth-card"><span class="eyebrow"><?=e(__('ui.account'))?></span><h1><?=e(__('auth.login'))?></h1><p class="muted"><?=e(__('app.slogan'))?></p><?php if(!empty($errors)): ?><div class="error-list"><?php foreach($errors as $error): ?><div><?=e($error)?></div><?php endforeach; ?></div><?php endif; ?><form method="post" action="<?=e(url('/login'))?>" class="form-stack"><?=csrf_field()?><label><?=e(__('auth.email'))?><input name="email" type="email" required autocomplete="email" value="<?=e(old('email'))?>"></label><label><?=e(__('auth.password'))?><input name="password" type="password" required autocomplete="current-password"></label><label class="check"><input type="checkbox" name="remember" value="1"> <span><?=e(__('auth.remember'))?></span></label><button class="btn primary big" type="submit"><?=e(__('auth.submit_login'))?></button></form><div class="auth-links"><a href="<?=e(url('/forgot-password'))?>"><?=e(__('auth.forgot'))?></a><a href="<?=e(url('/register'))?>"><?=e(__('auth.register'))?></a></div></div></div>
